import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { test } from "node:test";
import { fileURLToPath } from "node:url";
import { parseCount } from "../src/count.js";

test("the parser accepts a count in range", () => {
  assert.equal(parseCount("3"), 3);
});

const validCounts = [
  ["1", 1],
  ["20", 20],
  ["003", 3],
  ["00020", 20],
] as const;

const invalidCounts = [
  "", "0", "000", "21", "9007199254740992", "9".repeat(400),
  "+3", "-3", " 3", "3 ", "3\t", "3\n", "3\r\n",
  "3.5", "3.0", "3e0", "3junk", "0x3", "３", "٣",
];

test("the parser accepts the inclusive boundaries and leading zeroes", () => {
  for (const [raw, expected] of validCounts) {
    assert.equal(parseCount(raw), expected, JSON.stringify(raw));
  }
});

test("the parser rejects anything outside the decimal count contract", () => {
  for (const raw of invalidCounts) {
    assert.equal(parseCount(raw), null, JSON.stringify(raw));
  }
});

const commandPath = fileURLToPath(new URL("../dist/report.js", import.meta.url));

test("the emitted CLI prints the requested count exactly", () => {
  for (const [raw, expected] of validCounts) {
    const result = spawnSync(process.execPath, [commandPath, raw], { encoding: "utf8" });
    assert.equal(result.error, undefined);
    assert.equal(result.status, 0, JSON.stringify(raw));
    assert.equal(result.stdout, `Pieces: ${expected}\n`, JSON.stringify(raw));
    assert.equal(result.stderr, "", JSON.stringify(raw));
  }
});

test("the emitted CLI rejects invalid and missing input with the diagnostic", () => {
  for (const args of [[], ...invalidCounts.map((raw) => [raw])]) {
    const result = spawnSync(process.execPath, [commandPath, ...args], { encoding: "utf8" });
    assert.equal(result.error, undefined);
    assert.equal(result.status, 1, JSON.stringify(args));
    assert.equal(result.stdout, "", JSON.stringify(args));
    assert.equal(result.stderr, "Count must contain only decimal digits and be between 1 and 20.\n", JSON.stringify(args));
  }
});

