import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { test } from "node:test";
import { parseCount } from "../src/count.js";

const cliPath = fileURLToPath(new URL("../dist/report.js", import.meta.url));
const validInputs = [
  ...Array.from({ length: 20 }, (_, index) => String(index + 1)),
  "01", "0003", "020", `${"0".repeat(100)}1`,
];
const invalidInputs = [
  "", "0", "00", "21", "999999999999999999999999999999",
  "-1", "+1", " 1", "1 ", "\t1", "1\n", "1\r\n", "1\u2028",
  "1.5", "1e1", "0x10", "1piece", "3junk", "١", "１",
  "NaN", "Infinity",
];

test("the parser accepts a count in range", () => {
  assert.equal(parseCount("3"), 3);
});

test("the parser accepts every count boundary and leading zeroes", () => {
  for (const input of validInputs) {
    assert.equal(parseCount(input), Number(input), JSON.stringify(input));
  }
});

test("the parser rejects nondecimal input and out-of-range counts", () => {
  for (const input of [...invalidInputs, "1\u0000"]) {
    assert.equal(parseCount(input), null, JSON.stringify(input));
  }
});

test("the emitted CLI prints exactly the requested count", () => {
  for (const input of validInputs) {
    const result = spawnSync(process.execPath, [cliPath, input], { encoding: "utf8" });
    assert.equal(result.error, undefined, JSON.stringify(input));
    assert.equal(result.signal, null, JSON.stringify(input));
    assert.equal(result.status, 0, JSON.stringify(input));
    assert.equal(result.stdout, `Pieces: ${Number(input)}\n`, JSON.stringify(input));
    assert.equal(result.stderr, "", JSON.stringify(input));
  }
});

test("the emitted CLI diagnoses invalid and missing input", () => {
  for (const args of [[], ...invalidInputs.map((input) => [input])]) {
    const result = spawnSync(process.execPath, [cliPath, ...args], { encoding: "utf8" });
    assert.equal(result.error, undefined, JSON.stringify(args));
    assert.equal(result.signal, null, JSON.stringify(args));
    assert.equal(result.status, 1, JSON.stringify(args));
    assert.equal(result.stdout, "", JSON.stringify(args));
    assert.equal(result.stderr, "Count must contain only decimal digits and be between 1 and 20.\n", JSON.stringify(args));
  }
});

